package com.cloudmusic2ktv.dlna;
import android.app.*;import android.os.*;import android.content.*;import android.net.wifi.WifiManager;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity{
 EditText url; LinearLayout list; WifiManager.MulticastLock lock;
 public void onCreate(Bundle b){super.onCreate(b); LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(24,24,24,24);url=new EditText(this);url.setHint("视频 URL（https://…/video.mp4）");root.addView(url);Button scan=new Button(this);scan.setText("搜索 DLNA 设备");root.addView(scan);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);setContentView(root);Intent i=getIntent();if(Intent.ACTION_SEND.equals(i.getAction()))url.setText(i.getStringExtra(Intent.EXTRA_TEXT));scan.setOnClickListener(v->discover());}
 void discover(){list.removeAllViews(); WifiManager w=(WifiManager)getSystemService(WIFI_SERVICE);lock=w.createMulticastLock("url_display_dlna");lock.setReferenceCounted(true);lock.acquire();TextView t=new TextView(this);t.setText("正在搜索…");list.addView(t);new Thread(()->{try{List<DlnaRenderer> rs=DlnaRenderer.discover(4000);runOnUiThread(()->{list.removeAllViews();if(rs.isEmpty()){TextView e=new TextView(this);e.setText("没有发现 DLNA 播放设备");list.addView(e);}for(DlnaRenderer r:rs){Button x=new Button(this);x.setText(r.toString());x.setOnClickListener(v->play(r));list.addView(x);}});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show());}finally{if(lock!=null)lock.release();}}).start();}
 void play(DlnaRenderer r){String u=url.getText().toString().trim();if(u.isEmpty()){url.setError("请输入视频 URL");return;}new Thread(()->{try{r.play(u);runOnUiThread(()->Toast.makeText(this,"已发送播放命令",Toast.LENGTH_SHORT).show());}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"投送失败："+e.getMessage(),Toast.LENGTH_LONG).show());}}).start();}
}
